CREATE TABLE IF NOT EXISTS market_cache (id INTEGER PRIMARY KEY CHECK(id=1), attempted_at INTEGER NOT NULL DEFAULT 0, fetched_at INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL DEFAULT '[]'); INSERT OR IGNORE INTO market_cache(id) VALUES(1); CREATE TABLE IF NOT EXISTS market_observations (symbol TEXT NOT NULL, observed_at INTEGER NOT NULL, price REAL NOT NULL CHECK(price>0), PRIMARY KEY(symbol,observed_at));